package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.executing.*;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.shipping.*;import com.intermarche.backoffice.domain.wms.*;import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import org.junit.jupiter.api.Test;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(ShipmentDepartureWorkflowTest.class)
class ShipmentDepartureWorkflowTest extends TraceabilityWorkflowTest {
 @Test void operatorDispatchIsTrackedAndReturningAnEmptyToteNeverCreditsGoods(){line();Stock s=stock();pick(s);long customer=QuarkusTransaction.requiringNew().call(()->{var item=PickedItem.<PickedItem>findById(f.item());var lot=em.createQuery("select lot from Lot lot join lot.lines l where l=?1",Lot.class).setParameter(1,item.lotLine).getSingleResult();lot.fulfillment.chunks.add(lot.chunk);var b=new Buffer();b.bufferCode="OUT-"+key().substring(0,8);b.building=Building.findById(f.building());b.persist();item.loadedTote.buffer=b;return lot.fulfillment.order.id;});var input=Map.of("storeId",f.store(),"orderId",customer,"toteIds",List.of(QuarkusTransaction.requiringNew().call(()->PickedItem.<PickedItem>findById(f.item()).loadedTote.id)),"recipient","Client test","transportReference","REMISE-1","mode","CUSTOMER","requestKey",key());var dispatch=given().auth().oauth2(f.picker()).contentType("application/json").body(input).post("/shipments").then().statusCode(200).extract();long id=dispatch.jsonPath().getLong("id");given().auth().oauth2(f.picker()).contentType("application/json").body(input).post("/shipments").then().statusCode(200);given().auth().oauth2(f.picker()).get("/shipments/"+id+"?storeId="+f.store()).then().statusCode(200).body("lines[0].name",org.hamcrest.Matchers.is("Produit terrain"));long tote=((Number)((List<?>)input.get("toteIds")).getFirst()).longValue();for(int n=0;n<2;n++)given().auth().oauth2(f.picker()).contentType("application/json").body(Map.of("storeId",f.store(),"toteId",tote)).post("/shipments/"+id+"/returns").then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{eq(18,stocks.availability(s.account(),null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical);assertEquals(1,Shipment.count("store.id",f.store()));assertEquals(LoadedTote.Status.DELIVERED,LoadedTote.<LoadedTote>findById(tote).status);});}
 @jakarta.inject.Inject com.intermarche.backoffice.engine.stock.PickedStockCoordinator trace;
 @Test void twoTotesCanDepartSeparatelyAndKeepTheOrderPartiallyShippedUntilTheSecondDeparture(){line();Stock s=stock();pick(s);attach(f.second());Long[] ids=QuarkusTransaction.requiringNew().call(()->{var item=PickedItem.<PickedItem>findById(f.item());item.quantity=BigDecimal.ONE;var other=new PickedItem();other.product=item.product;other.lotLine=item.lotLine;other.sourceLocation=item.sourceLocation;other.quantity=BigDecimal.ONE;other.status=PickedItem.PickStatus.PICKED;other.loadedTote=LoadedTote.find("tote.code=?1 and status=?2",f.second(),LoadedTote.Status.IN_USE).firstResult();other.persist();var execution=com.intermarche.backoffice.client.PickingExecution.<com.intermarche.backoffice.client.PickingExecution>findById(f.execution());execution.itemsToPick.add(other);var lot=em.createQuery("select lot from Lot lot join lot.lines l where l=?1",Lot.class).setParameter(1,item.lotLine).getSingleResult();lot.fulfillment.chunks.add(lot.chunk);var b=new Buffer();b.bufferCode="PART-"+key().substring(0,8);b.building=Building.findById(f.building());b.persist();item.loadedTote.buffer=b;other.loadedTote.buffer=b;em.flush();trace.syncLines(Store.findById(f.store()),List.of(item.lotLine.id),null,"split-parcel-test-"+key());return new Long[]{lot.fulfillment.order.id,item.loadedTote.id,other.loadedTote.id};});for(int n=1;n<=2;n++){var body=Map.of("storeId",f.store(),"orderId",ids[0],"toteIds",List.of(ids[n]),"recipient","Client test","transportReference","PARTIAL-"+n,"mode","CUSTOMER","requestKey",key());given().auth().oauth2(f.picker()).contentType("application/json").body(body).post("/shipments").then().statusCode(200);given().auth().oauth2(f.picker()).contentType("application/json").body(body).post("/shipments").then().statusCode(200);final int step=n;QuarkusTransaction.requiringNew().run(()->{assertEquals(step==1?"PARTIALLY_SHIPPED":"SHIPPED",com.intermarche.backoffice.domain.order.Order.<com.intermarche.backoffice.domain.order.Order>findById(ids[0]).status);eq(20-step,stocks.availability(s.account(),null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical);});}}

}
